text=torch.load(ROOT/'artifacts/p1b_coordinates_calib.pt',weights_only=True,mmap=True);_,tn=reconstruct(host,delta,text);T=aug(tn.reshape(-1,768));construction=unpack(torch.load(ROOT/'artifacts/p1b_coordinates_format_a.pt',weights_only=True,mmap=True));_,pn=reconstruct(host,delta,construction);A=aug(pn);full=torch.load(ROOT/'artifacts/p2e_full_prefix_b.pt',weights_only=True,mmap=True);X=aug(full['captures']['1.ln1']);starts=torch.tensor(full['request']['program_starts']);positions=starts+7;Qinput=X[torch.arange(512),positions];coords=torch.load(ROOT/'experiments/p1b_coordinates/circuit.pt',weights_only=True);ids=coords['allowed_token_ids'];lookup={int(t):i%10 for i,t in enumerate(ids[:20])};tok=full['inputs'];actualdigits=torch.tensor([[lookup[int(tok[i,starts[i]+j])] for j in (0,1,2,4,5,6)] for i in range(512)]);expected=torch.stack([((actualdigits[:,j,None]>>torch.arange(4))&1)+((actualdigits[:,j+3,None]>>torch.arange(4))&1) for j in range(3)],1)
P=host['transformer.h.1.attn.c_proj.weight'].double();values=torch.load(ROOT/'artifacts/p1_coordinates_calib.pt',weights_only=True,mmap=True)['captures']['1.attn_values'].reshape(-1,768).double();energy=[float((values[:,64*h:64*(h+1)]@P[:,64*h:64*(h+1)].T).square().mean()) for h in range(12)];heads=sorted(range(12),key=lambda h:energy[h])[:4];W=host['transformer.h.1.attn.c_attn.weight'].double();bias=host['transformer.h.1.attn.c_attn.bias'].double();eqflag=token['attention_kind_decoder'][:,4].clone();eqflag[-1]-=(T@eqflag).mean();F=aux['frame'];fieldmean=(((T[:,:768]-b)/g)@F).mean(0);native=[];qparameters=[]
